using System.Runtime.InteropServices;using Essco.Application.Configuration;using Essco.Application.Customers;using Essco.Application.Payroll;using Microsoft.Extensions.Options;namespace Essco.SapBridge.Worker;
public sealed class ComSapPayrollGateway(IOptions<EsscoOptions> options,ILogger<ComSapPayrollGateway> logger):ISapPayrollGateway
{public ValueTask<SapProcessingResult>CreateJournalAsync(PayrollJournal journal,CancellationToken token){token.ThrowIfCancellationRequested();if(!options.Value.Sap.Enabled)return ValueTask.FromResult(new SapProcessingResult(false,null,"La conexión SAP no está habilitada.",false));var done=new TaskCompletionSource<SapProcessingResult>(TaskCreationOptions.RunContinuationsAsynchronously);var thread=new Thread(()=>{try{done.TrySetResult(Create(journal));}catch(COMException ex){logger.LogWarning("Error COM SAP {Code} procesando planilla {Payroll}",ex.ErrorCode,journal.Number);done.TrySetResult(new(false,null,$"Error COM SAP ({ex.ErrorCode}).",true));}catch(Exception ex){logger.LogError(ex,"Error procesando planilla {Payroll}",journal.Number);done.TrySetResult(new(false,null,"Error interno del adaptador SAP.",true));}}){IsBackground=true,Name="Essco SAP DI API Payroll Journal"};thread.SetApartmentState(ApartmentState.STA);thread.Start();return new ValueTask<SapProcessingResult>(done.Task);}
 private SapProcessingResult Create(PayrollJournal x){dynamic? company=null;dynamic? entry=null;try{var type=Type.GetTypeFromProgID("SAPbobsCOM.Company")??throw new COMException("SAP DI API no está registrada.");company=Activator.CreateInstance(type)??throw new COMException("No fue posible crear Company.");var c=options.Value.Sap;company.Server=c.Server;company.CompanyDB=c.CompanyDatabase;company.UserName=c.UserName;company.Password=c.Password;company.DbUserName=c.DatabaseUserName;company.DbPassword=c.DatabasePassword;company.LicenseServer=c.LicenseServer;company.DbServerType=c.DatabaseServerType;company.UseTrusted=false;var connected=(int)company.Connect();if(connected!=0)return Failure(company,connected,true);entry=company.GetBusinessObject(30);entry.DueDate=DateTime.Today;entry.Memo=$"[{x.Number}] {x.Memo}";for(var i=0;i<x.Lines.Count;i++){if(i>0)entry.Lines.Add();var line=x.Lines.ElementAt(i);entry.Lines.AccountCode=line.AccountCode;entry.Lines.Debit=(double)line.Debit;entry.Lines.Credit=(double)line.Credit;}var added=(int)entry.Add();if(added!=0)return Failure(company,added,false);return new(true,Convert.ToString(company.GetNewObjectKey()),null,false);}finally{Release(entry);try{if(company is not null&&(bool)company.Connected)company.Disconnect();}catch(COMException){}Release(company);}}
 private static SapProcessingResult Failure(dynamic c,int code,bool retry){string m="";try{c.GetLastError(out code,out m);}catch(COMException){}return new(false,null,$"SAP rechazó la operación ({code}): {m}",retry);}private static void Release(object? x){if(x is not null&&Marshal.IsComObject(x))Marshal.FinalReleaseComObject(x);}}
